/** Python reads precisely the CSV generated by resultsToCsv. */
export function buildLab04PythonAnalysis(studentCode: string, csvText: string): string {
  const script = "import csv\nimport io\nimport matplotlib.pyplot as plt\n\n_csv_text = CSV_PLACEHOLDER\n_all_rows = list(csv.DictReader(io.StringIO(_csv_text)))\n_valid = [r for r in _all_rows if r[\"status\"] in (\"Resolved\", \"Unresolved\")]\n_excluded = len(_all_rows) - len(_valid)\n\n_rows = [{\n    \"issue\": r[\"issue\"],\n    \"strategy\": r[\"strategy\"],\n    \"success\": r[\"success\"].strip().lower() == \"true\",\n    \"elapsed_ms\": float(r[\"elapsedMs\"]),\n    \"tool_bytes\": int(r[\"toolBytes\"]),\n    \"tool_messages\": int(r[\"toolMessages\"]),\n    \"model_calls\": int(r[\"modelCalls\"]),\n    \"model_tokens\": int(r[\"modelTokens\"]),\n    \"attempts\": int(r[\"attempts\"])\n} for r in _valid]\n\nprint(\"LAB 04 | EXPERIMENTAL ANALYSIS\")\nprint(\"CSV records:\", len(_all_rows), \"| completed repairs:\", len(_rows),\n      \"| excluded API/execution errors:\", _excluded)\n\nif not _rows:\n    print(\"No completed repair trials. Check the API/worker error log and rerun.\")\nelse:\n    _summary = summarize_runs(_rows)\n    _names = (\"reactive\", \"intelligent\")\n\n    print(\"\\nOVERALL STRATEGY COMPARISON\")\n    print(f'{\"Strategy\":<13} {\"N\":>4} {\"Resolved\":>9} {\"Success\":>9} {\"Mean time\":>12} {\"Worker bytes\":>14} {\"Tokens\":>10}')\n    print(\"-\" * 80)\n    for _name in _names:\n        _sample = [r for r in _rows if r[\"strategy\"] == _name]\n        if not _sample:\n            print(f\"{_name:<13} No completed trials\")\n            continue\n        _result = _summary[_name]\n        _n = len(_sample)\n        _passed = sum(r[\"success\"] for r in _sample)\n        _tokens = sum(r[\"model_tokens\"] for r in _sample) / _n\n        print(f'{_name:<13} {_n:>4} {_passed:>9} {_result[\"success_rate\"]*100:>8.1f}% '\n              f'{_result[\"mean_elapsed_ms\"]/1000:>10.2f}s '\n              f'{_result[\"mean_tool_bytes\"]:>14.0f} {_tokens:>10.0f}')\n\n    print(\"\\nPER-ISSUE BREAKDOWN\")\n    print(f'{\"Issue\":<12} {\"Strategy\":<13} {\"Solved/N\":>10} {\"Success\":>10} {\"Mean time\":>11} {\"Worker bytes\":>13}')\n    print(\"-\" * 75)\n    for _issue in (\"checkout\", \"queue\", \"security\"):\n        for _name in _names:\n            _subset = [r for r in _rows if r[\"issue\"] == _issue and r[\"strategy\"] == _name]\n            if not _subset:\n                print(f'{_issue:<12} {_name:<13} {\"N/A\":>10}')\n                continue\n            _part = summarize_runs(_subset)[_name]\n            _n = len(_subset)\n            print(f'{_issue:<12} {_name:<13} {str(sum(r[\"success\"] for r in _subset))+\"/\"+str(_n):>10} '\n                  f'{_part[\"success_rate\"]*100:>9.1f}% '\n                  f'{_part[\"mean_elapsed_ms\"]/1000:>9.2f}s '\n                  f'{_part[\"mean_tool_bytes\"]:>13.0f}')\n\n    def _value(_strategy, _metric):\n        _subset = [r for r in _rows if r[\"strategy\"] == _strategy]\n        if not _subset:\n            return None\n        if _metric == \"success\":\n            return 100 * sum(r[\"success\"] for r in _subset) / len(_subset)\n        return sum(r[_metric] for r in _subset) / len(_subset)\n\n    def _make_bar(_metric, _title, _ylabel, _scale=1):\n        _actual = [_value(_n, _metric) for _n in _names]\n        _vals = [(v or 0) / _scale for v in _actual]\n        plt.figure(figsize=(7.4, 4.0))\n        plt.bar(list(_names), _vals, width=0.52)\n        plt.ylabel(_ylabel)\n        plt.title(_title)\n        plt.ylim(bottom=0)\n        plt.grid(axis=\"y\", alpha=0.2)\n        for _i, _v in enumerate(_actual):\n            _display = \"N/A\" if _v is None else f\"{_v/_scale:,.1f}\"\n            plt.annotate(_display, (_i, _vals[_i]), xytext=(0, 5),\n                         textcoords=\"offset points\", ha=\"center\", fontsize=10)\n        plt.tight_layout()\n\n    _make_bar(\"success\", \"Repair success by agent strategy\", \"Completed trials resolved (%)\")\n    _make_bar(\"elapsed_ms\", \"Mean repair time by agent strategy\", \"Time (seconds)\", 1000)\n    _make_bar(\"tool_bytes\", \"Mean tool-worker communication\", \"Exchanged JSON bytes\")\n    _make_bar(\"model_tokens\", \"Mean Gemini token consumption\", \"Input and output tokens\")\n\n    _issue_names = (\"checkout\", \"queue\", \"security\")\n    _rates = {}\n    for _name in _names:\n        _rates[_name] = []\n        for _issue in _issue_names:\n            _subset = [r for r in _rows if r[\"strategy\"] == _name and r[\"issue\"] == _issue]\n            _rates[_name].append(100 * sum(r[\"success\"] for r in _subset) / len(_subset) if _subset else 0)\n\n    plt.figure(figsize=(8.3, 4.3))\n    _positions = list(range(len(_issue_names)))\n    plt.bar([x - 0.2 for x in _positions], _rates[\"reactive\"], 0.39, label=\"Reactive\")\n    plt.bar([x + 0.2 for x in _positions], _rates[\"intelligent\"], 0.39, label=\"Intelligent\")\n    plt.xticks(_positions, [x.capitalize() for x in _issue_names])\n    plt.ylabel(\"Completed trials resolved (%)\")\n    plt.title(\"Repair success across the three software defects\")\n    plt.ylim(0, 110)\n    plt.legend()\n    plt.grid(axis=\"y\", alpha=0.2)\n    plt.tight_layout()\n";
  return studentCode + '\n\n' + script.replace('CSV_PLACEHOLDER', JSON.stringify(csvText));
}
